 public static void RenameMarcosAndFinishVisuals()
 {
  var s=EditorSceneManager.OpenScene("Assets/Scenes/Level1.unity");var actor=(SpeakerScript)new SerializedObject(All<CampRoutine>(s).Single()).FindProperty("mateo").objectReferenceValue;Undo.RecordObject(actor.gameObject,"Match the soldier to the designer letter");actor.name=actor.name.Replace("Mateo","Marcos");
  var keys=new System.Collections.Generic.HashSet<string>{"interactableName","displayName","missionTitle","returnObjective","title","description","transcription","label","promptText","callerName","name"};
  foreach(var component in All<MonoBehaviour>(s))
  {
   if(!component)continue;var data=new SerializedObject(component);var property=data.GetIterator();bool changed=false;while(property.NextVisible(true))if(property.propertyType==SerializedPropertyType.String&&keys.Contains(property.name)&&property.stringValue.IndexOf("Mateo",StringComparison.Ordinal)>=0){property.stringValue=property.stringValue.Replace("Mateo","Marcos");changed=true;}if(changed)data.ApplyModifiedProperties();
  }
  foreach(var text in All<TMP_Text>(s))if(text.text.IndexOf("Mateo",StringComparison.Ordinal)>=0){Undo.RecordObject(text,"Marcos player-facing name");text.text=text.text.Replace("Mateo","Marcos");}
  int lines=0;foreach(var guid in AssetDatabase.FindAssets("t:DialogueSO",new[]{"Assets/Systems"}))
  {
   var path=AssetDatabase.GUIDToAssetPath(guid);var line=AssetDatabase.LoadAssetAtPath<DialogueSO>(path);var data=new SerializedObject(line);var property=data.GetIterator();bool changed=false;while(property.NextVisible(true))if(property.propertyType==SerializedPropertyType.String&&(property.name=="_dialogueText"||property.name=="label")&&property.stringValue.IndexOf("Mateo",StringComparison.Ordinal)>=0){if(!changed){var backup="Library/ExperiencePresentation-backup/"+path;Directory.CreateDirectory(Path.GetDirectoryName(backup));if(!File.Exists(backup))File.Copy(path,backup);}property.stringValue=property.stringValue.Replace("Mateo","Marcos");changed=true;}if(changed){data.ApplyModifiedProperties();EditorUtility.SetDirty(line);lines++;}
  }
  var main=All<Camera>(s).Single(c=>c.CompareTag("MainCamera"));Undo.RecordObject(main,"Avoid clipping the distant terrain extension");float before=main.farClipPlane;main.farClipPlane=Mathf.Max(main.farClipPlane,3200);
  var shader=Shader.Find("StoryTell/InteractionPictogram");if(!shader||ShaderUtil.ShaderHasError(shader))throw new InvalidOperationException("Pictogram shader failed");var pathMaterial=Data+"/ReadableMouseIcon.mat";var material=AssetDatabase.LoadAssetAtPath<Material>(pathMaterial);if(!material){material=new Material(shader);AssetDatabase.CreateAsset(material,pathMaterial);}var interaction=All<InteractionUIManager>(s).Single();Set(interaction,"mouseIconMaterial",material);var image=(Image)new SerializedObject(interaction).FindProperty("interactionImage").objectReferenceValue;Undo.RecordObject(image,"Visible mouse pictogram");image.color=Color.white;
  foreach(var component in All<Component>(s))if(component&&PrefabUtility.IsPartOfPrefabInstance(component))PrefabUtility.RecordPrefabInstancePropertyModifications(component);EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);AssetDatabase.SaveAssets();File.WriteAllText("Library/ExperiencePresentation-final-authoring.txt","Renamed soldier to Marcos. Updated dialogue assets: "+lines+"\nFar clip: "+before+" -> "+main.farClipPlane+"\nFog: "+RenderSettings.fog+" "+RenderSettings.fogMode+" density="+RenderSettings.fogDensity+" start="+RenderSettings.fogStartDistance+" end="+RenderSettings.fogEndDistance);
 }
