 static void RegenerateSurvey(Scene s)
 {
  var reference=All<MapWorldReference>(s).Single();Undo.RecordObject(reference.WorldOrigin,"Survey only the correct terrain area");reference.WorldOrigin.position=new Vector3(150,0,420);reference.WorldOrigin.rotation=Quaternion.Euler(0,-90,0);Undo.RecordObject(reference,"Proportional geographical survey");reference.SetWorldSize(new Vector2(450,300));var serialized=new SerializedObject(reference);serialized.FindProperty("invertHorizontal").boolValue=false;serialized.FindProperty("invertVertical").boolValue=false;serialized.ApplyModifiedProperties();
  const int width=1536,height=1024;var values=new float[width*height];var colors=new Color32[values.Length];var origin=reference.WorldOrigin;for(int y=0;y<height;y++)for(int x=0;x<width;x++){var world=origin.position+origin.right*((x/(float)(width-1)-.5f)*450)+origin.forward*((y/(float)(height-1)-.5f)*300);values[y*width+x]=terrain.SampleHeight(world)+terrain.transform.position.y;}
  for(int y=0;y<height;y++)for(int x=0;x<width;x++){int index=y*width+x;float h=values[index];float dx=values[y*width+Mathf.Min(width-1,x+1)]-values[y*width+Mathf.Max(0,x-1)],dy=values[Mathf.Min(height-1,y+1)*width+x]-values[Mathf.Max(0,y-1)*width+x];float lineWidth=Mathf.Max(.035f,(Mathf.Abs(dx)+Mathf.Abs(dy))*.36f);bool contour=Mathf.Abs(h-Mathf.Round(h/2.5f)*2.5f)<lineWidth;float shade=Mathf.Clamp01(.5f+dx*.12f-dy*.16f);var paper=Color.Lerp(new Color(.67f,.65f,.49f),new Color(.84f,.82f,.66f),shade);float u=x/(float)(width-1),v=y/(float)(height-1);bool grid=Mathf.Min(Mathf.Abs(u*9-Mathf.Round(u*9)),Mathf.Abs(v*6-Mathf.Round(v*6)))<.008f;colors[index]=contour?new Color(.29f,.30f,.21f):grid?Color.Lerp(paper,new Color(.40f,.40f,.29f),.28f):paper;}
  void Pixel(int x,int y,Color color){if(x>=0&&x<width&&y>=0&&y<height)colors[y*width+x]=color;}
  void Line(int x0,int y0,int x1,int y1,int radius){int n=Mathf.Max(Mathf.Abs(x1-x0),Mathf.Abs(y1-y0));for(int i=0;i<=n;i++){int x=Mathf.RoundToInt(Mathf.Lerp(x0,x1,i/(float)Mathf.Max(1,n))),y=Mathf.RoundToInt(Mathf.Lerp(y0,y1,i/(float)Mathf.Max(1,n)));for(int a=-radius;a<=radius;a++)for(int b=-radius;b<=radius;b++)Pixel(x+a,y+b,new Color(.21f,.23f,.16f));}}
  Line(8,8,width-9,8,2);Line(8,height-9,width-9,height-9,2);Line(8,8,8,height-9,2);Line(width-9,8,width-9,height-9,2);Line(42,height-68,120,height-68,2);Line(120,height-68,101,height-53,2);Line(120,height-68,101,height-83,2);Line(43,height-43,43,height-23,1);Line(57,height-43,57,height-23,1);Line(43,height-23,57,height-43,1);
  foreach(var r in All<MeshRenderer>(s).Where(r=>r.name.StartsWith("Tent_")||r.name.StartsWith("Carpa del campamento")||r.name.StartsWith("LetterCamp_"))){var center=r.bounds.center;var d=center-origin.position;float u=Vector3.Dot(d,origin.right)/450+.5f,v=Vector3.Dot(d,origin.forward)/300+.5f;if(u<=0||u>=1||v<=0||v>=1)continue;int x=Mathf.RoundToInt(u*(width-1)),y=Mathf.RoundToInt(v*(height-1));int rx=Mathf.Max(3,Mathf.RoundToInt(r.bounds.extents.z/450*width)),ry=Mathf.Max(3,Mathf.RoundToInt(r.bounds.extents.x/300*height));for(int a=-rx;a<=rx;a++)for(int b=-ry;b<=ry;b++)Pixel(x+a,y+b,new Color(.33f,.34f,.25f));}
  var texture=new Texture2D(width,height,TextureFormat.RGB24,false);texture.SetPixels32(colors);texture.Apply();string path=Data+"/Level1SectorSurvey.png";File.WriteAllBytes(path,texture.EncodeToPNG());UnityEngine.Object.DestroyImmediate(texture);AssetDatabase.ImportAsset(path);var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.npotScale=TextureImporterNPOTScale.None;importer.mipmapEnabled=false;importer.wrapMode=TextureWrapMode.Clamp;importer.maxTextureSize=2048;importer.SaveAndReimport();var renderer=reference.GetComponent<MeshRenderer>();var material=new Material(renderer.sharedMaterial){name="CorrectedSectorPaper"};material.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(path));material.SetTextureScale("_BaseMap",Vector2.one);material.SetTextureOffset("_BaseMap",Vector2.zero);AssetDatabase.CreateAsset(material,Data+"/SectorPaper.mat");renderer.sharedMaterial=material;
 }
 static void ExtendHorizon(Scene s)
 {
  var skirt=All<MeshFilter>(s).Single(f=>f.name=="HorizonTerrainSkirt");var origin=terrain.transform.position;var size=terrain.terrainData.size;var corners=new[]{new Vector3(0,0,0),new Vector3(size.x,0,0),new Vector3(size.x,0,size.z),new Vector3(0,0,size.z)};float[] bands={0,20,55,110,200,330,500,850};const int samples=192;var vertices=new System.Collections.Generic.List<Vector3>();var uv=new System.Collections.Generic.List<Vector2>();var triangles=new System.Collections.Generic.List<int>();var layer=terrain.terrainData.terrainLayers.First();
  for(int side=0;side<4;side++){int offset=vertices.Count;for(int row=0;row<bands.Length;row++)for(int i=0;i<=samples;i++){float t=i/(float)samples,d=bands[row];var a=Vector3.Lerp(corners[side],corners[(side+1)%4],t);var direction=(corners[(side+1)%4]-corners[side]).normalized;var outward=new Vector3(direction.z,0,-direction.x);var world=origin+a+outward*d+direction*(d*(2*t-1));float edge=terrain.SampleHeight(origin+a)+origin.y;float coast=Mathf.SmoothStep(0,1,Mathf.Clamp01((d-45)/500));world.y=Mathf.Lerp(edge,-1.5f,coast)+(Mathf.PerlinNoise(world.x*.007f,world.z*.007f)-.5f)*3*Mathf.Sin(Mathf.PI*Mathf.Clamp01(d/545));vertices.Add(skirt.transform.InverseTransformPoint(world));uv.Add(new Vector2(world.x/Mathf.Max(1,layer.tileSize.x),world.z/Mathf.Max(1,layer.tileSize.y)));}for(int row=0;row<bands.Length-1;row++)for(int i=0;i<samples;i++){int a=offset+row*(samples+1)+i,b=a+1,c=a+samples+1,e=c+1;triangles.AddRange(new[]{a,b,c,b,e,c});}}
  var mesh=new Mesh{name="Continuous coastal ground"};mesh.SetVertices(vertices);mesh.SetUVs(0,uv);mesh.SetTriangles(triangles,0);mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,Data+"/CoastalGround.asset");skirt.sharedMesh=mesh;var mat=new Material(Shader.Find("Universal Render Pipeline/Lit"));mat.SetTexture("_BaseMap",layer.diffuseTexture);mat.SetFloat("_Smoothness",.16f);mat.SetColor("_BaseColor",new Color(.94f,.96f,.93f));AssetDatabase.CreateAsset(mat,Data+"/CoastalGround.mat");skirt.GetComponent<MeshRenderer>().sharedMaterial=mat;
 }
 static void GroupKitchen(Scene s)
